import { AsyncPipe, CommonModule } from '@angular/common';
import { Component, inject, OnInit, signal, viewChild } from '@angular/core';
import {
  FormBuilder,
  FormsModule,
  ReactiveFormsModule,
  Validators,
} from '@angular/forms';
import {
  IonAlert,
  IonBackButton,
  IonButton,
  IonButtons,
  IonContent,
  IonHeader,
  IonItem,
  IonList,
  IonSearchbar,
  IonTitle,
  IonToolbar,
} from '@ionic/angular/standalone';
import parse, {
  BibleReferenceParserResult,
} from '@hey-bible/bible-reference-parser';
import {
  catchError,
  firstValueFrom,
  map,
  merge,
  of,
  shareReplay,
  startWith,
  Subject,
  switchMap,
} from 'rxjs';
import { getAllBooks } from 'supabase/functions/_shared/book';
import { titleCase } from 'title-case';
import { BibleId } from 'supabase/functions/_shared/bibles';
import { getRoutePath, loginRoutePath } from '../app.routes';
import { AlertService } from '../common/alert/alert.service';
import { ResultsComponent } from '../common/results/results.component';
import { LocalStorageService } from '../common/storage/local-storage.service';
import { SupabaseService } from '../common/supabase/supabase.service';
import { TimerService } from '../common/timer/timer.service';
import { Verse } from '../common/verse/verse';
import { EmptyComponent } from '../favorites/empty/empty.component';

const BIBLE_BOOKS = getAllBooks();

@Component({
  selector: 'app-public',
  templateUrl: './public.page.html',
  styleUrls: ['./public.page.scss'],
  imports: [
    IonAlert,
    IonBackButton,
    IonButton,
    IonButtons,
    IonItem,
    IonList,
    IonSearchbar,
    IonContent,
    IonHeader,
    IonTitle,
    IonToolbar,
    CommonModule,
    FormsModule,
    ReactiveFormsModule,
    ResultsComponent,
    AsyncPipe,
    EmptyComponent,
  ],
})
export class PublicPage implements OnInit {
  searchbar = viewChild<IonSearchbar>('searchbar');

  private readonly supabaseService = inject(SupabaseService);
  private readonly timerService = inject(TimerService);
  private readonly alertService = inject(AlertService);
  private readonly localStorage = inject(LocalStorageService);

  readonly alertButtons = ['OK'];
  readonly emptyMessage =
    'To get started, enter a Bible verse in the search field at the top of the page.';
  readonly headerMessage = 'Welcome to Hey Bible!';
  readonly welcomeMessage =
    'You are currently viewing the limited public preview. To access features like saved searches, favorites, notes and more, please login.';
  readonly loginRouterlink = getRoutePath(loginRoutePath);
  controlKnobsIcon = 'node_modules/openmoji/color/svg/1F39B.svg'; // 🎛️ Control Knobs

  // Public bibles available to unauthenticated users
  private readonly publicBibles = [
    {
      id: 'private-bible-esv',
      name: 'English Standard Version',
      abbreviation: 'esv',
    },
    {
      id: 'de4e12af7f28f599-02',
      name: 'King James Version',
      abbreviation: 'engKJV',
    },
  ];

  private refreshResults$ = new Subject<{ query: string | null | undefined }>();

  showSuggestions = signal(false);

  formGroup = inject(FormBuilder).group({
    query: [
      '',
      [Validators.required, Validators.pattern(/(.*)\s*[0-9]+(:[0-9]+)?\s*$/)],
    ],
  });

  filteredBooks$ = this.formGroup.controls.query.valueChanges.pipe(
    startWith(''),
    map((query) => {
      if (
        !query ||
        query.includes(':') ||
        /\d/.test(query.split(' ').pop() || '')
      ) {
        return [];
      }
      const lowerCaseQuery = query.toLowerCase();
      return BIBLE_BOOKS.filter((book) =>
        book.toLowerCase().startsWith(lowerCaseQuery)
      ).map((book) => titleCase(book));
    }),
    shareReplay(1)
  );

  isOpen = false;

  results$ = merge(this.formGroup.valueChanges, this.refreshResults$).pipe(
    this.timerService.debounceTime(1000),
    map((value: any) => value.query?.trim().replace(/\s+/g, ' ')),
    switchMap(async (query) => {
      if (this.formGroup.invalid || !query) {
        return Promise.resolve({
          results: [] as Verse[],
          error: 'Enter a complete Bible verse eg John 3:16.',
        });
      }

      const result = normalizeBibleParserResult(parse(query));

      if (!result || !result?.verses.length || result.chapter === 0) {
        return Promise.resolve({
          results: [] as Verse[],
          error: 'Enter a complete Bible verse eg John 3:16.',
        });
      }

      // TODO BG the private bible APIs don't handle the entire chapter query
      const { book, chapter, verses: searchVerses } = result;
      const start_verse =
        searchVerses === 'ALL' ? 1 : Number(searchVerses.at(0)!);
      const end_verse =
        searchVerses === 'ALL' ? 999 : Number(searchVerses.at(-1));

      // Get selected bible, default to ESV
      const selectedBibleId = 
        (this.localStorage.getItem('selected-public-bible-id') as BibleId) || 
        'private-bible-esv';

      return this.supabaseService.searchPublicVerses(
        selectedBibleId,
        book,
        chapter,
        start_verse,
        end_verse
      );
    }),
    catchError((error) => {
      return of({
        results: [] as Verse[],
        error: error.message,
      });
    }),
    shareReplay(1)
  );

  ngOnInit() {
    this.isOpen = true;
  }

  handleInput(event: any) {
    const query = event.target.value || '';
    this.formGroup.controls.query.setValue(query, { emitEvent: true });
    this.showSuggestions.set(true);
  }

  async selectBook(book: string) {
    this.formGroup.controls.query.setValue(book + ' ', { emitEvent: true });
    this.showSuggestions.set(false);
    await firstValueFrom(this.timerService.timer(150)); // Wait before focusing the searchbar
    const searchbar = this.searchbar();
    if (!searchbar) {
      return;
    }
    const value = searchbar.value;
    searchbar.setFocus();
    searchbar.value = '';
    searchbar.value = value;
  }

  async hideSuggestionsWithDelay() {
    await firstValueFrom(this.timerService.timer(150));
    this.showSuggestions.set(false);
  }

  async presentAlert() {
    const selectedBibleId = 
      this.localStorage.getItem('selected-public-bible-id') || 
      'private-bible-esv';

    return this.alertService.presentAlert({
      header: 'Select Bible Version',
      buttons: [
        {
          text: 'Cancel',
          role: 'cancel',
        },
        {
          text: 'OK',
          role: 'confirm',
          handler: (value: string) => {
            this.localStorage.setItem('selected-public-bible-id', value);
            this.refreshResults$.next({ query: this.formGroup.value.query });
          },
        },
      ],
      inputs: this.publicBibles.map((bible) => ({
        label: bible.name,
        type: 'radio' as const,
        value: bible.id,
        checked: bible.id === selectedBibleId,
      })),
    });
  }
}

function normalizeBibleParserResult(result?: BibleReferenceParserResult) {
  if (!result) {
    return null;
  }

  return {
    ...result,
    chapter: Number(result.chapter),
  };
}
